for (const k of Array.isArray(r.kanaele) ? r.kanaele : []) {
  const id = Number(k && k.kanal_id);
  if (!(id > 0) || erledigt.has(id)) continue;
  const weg = String(k.anmeldeweg || 'facebook');
  const host = String(k.host || HOSTS.facebook);
  const nurNutzer = weg === 'instagram';
  // Storys gibt es laut Vertrag nur bei der Anmeldung über Facebook; die Liste liefert solche Accounts hier nicht. Kommt doch einer,
  // gilt er als erledigt (übersprungen, ohne Abruf, Speichern und Fehler), damit er keine Portion blockiert (Stefan 18.10.2026)
  if (nurNutzer && ART === 'stuendlich') { out.push({ json: { start: true, kanal_id: id, ueberspringen: true } }); continue; }
  const reihenfolge = (Array.isArray(k.reihenfolge) ? k.reihenfolge : []).filter(v => v === 'nutzer' || (v === 'seite' && !nurNutzer));
  const api = String(k.api || '');
  const j = { start: true, kanal_id: id, ig_id: String(k.ig_id || ''), api, reihenfolge,
    schluessel_fehler: k.schluessel_fehler === true || !reihenfolge.length };
  // Adresse muss zum Host und der Host zum Anmeldeweg passen (Stefan 18.10.2026)
  const hostPasst = HOSTS[weg] === host && api.startsWith('https://' + host + '/');
  if (!/^[0-9]{1,30}$/.test(j.ig_id) || !hostPasst || !/^https:\/\/graph\.(facebook|instagram)\.com\/v[0-9]{1,3}\.[0-9]{1,2}$/.test(api)) j.ungueltig = true;
