  if (k.schluessel_fehler === true || !Array.isArray(k.reihenfolge) || !k.reihenfolge.length) {
    leer.abbruch = { code: 'schluessel', text: 'Zugangsschlüssel nicht lesbar.', abgelaufen: false, pause: 0 };
    return ende(leer);
  }
  const st = { kanal_id: k.kanal_id, api: k.api, ig_id: k.ig_id, reihenfolge: k.reihenfolge.slice(), vi: 0, bestaetigt: false,
    erfolg_variante: null, varianten_fehler: {}, offen: [], abrufe: 0, abbruch: null, hinweis: null };
  beginnen(st, k);
  return verteilen(st);
}
const anfragen = $('Anfrage').all();
if (!anfragen.length || !anfragen[0].json || !anfragen[0].json.st) throw new Error('Abruf steuern: Zustand fehlt (Anfrage ohne st).');
const st = kopie(anfragen[0].json.st);
auswerten(st, anfragen, ein);
return verteilen(st);

// Kanal abschließen (Stefan 18.10.2026): kurze Übersicht je Kanal, ohne Schlüssel und ohne Kennzahlen.
// stopp_alle = App-Grenze erreicht: übrige Kanäle werden übersprungen und bleiben fällig.
const s = $('Abruf steuern').last().json;
const sp = $('Ergebnis speichern').last().json || {};
const fe = $input.first().json || {};
const rs = sp.r && typeof sp.r === 'object' ? sp.r : null;
const rf = fe.r && typeof fe.r === 'object' ? fe.r : null;
return [{ json: {
  kanal_id: s.kanal_id,
  abrufe: s.abrufe || 0,
  gespeichert: !!(rs && rs.ok === true),
  vollstaendig: !!(rs && rs.ok === true && rs.vollstaendig === true),
  speicher_fehler: rs && rs.ok !== true ? String(rs.fehler || '').slice(0, 200) : '',
  fehler: s.fehler ? String(s.fehler.text || '').slice(0, 200) : '',
  status: rf && rf.status ? String(rf.status) : '',
  meldung_faellig: !!(rf && rf.meldung_faellig === true),
  stopp_alle: s.stopp_alle === true,
  uebersprungen: s.uebersprungen === true,
  uebersicht: s.uebersicht || {}
} }];

