// Bilder verteilen – TALENTS 2, Migration 193 (Stefan 01.11.2026, „Bild speichern“): Vorschaubilder der Storys einmal und dauerhaft speichern, solange die
// Meta-Adresse noch gilt (gleicher Lauf wie der Abruf). Abgelaufene Storys bleiben ohne Bild. Ein Fehler beim Laden oder Speichern lässt den Lauf nie
// scheitern; ohne gespeichertes Bild bleibt es bei der Adresse wie bisher.
// Je Bild ein Eintrag für „Bild laden“; ohne Bild ein Eintrag „nichts zu laden“, damit der Kanal immer bei „Kanal weiter“ ankommt.
const k = $('Kanal abschließen').last().json || {};
const j = $input.first().json || {};
const liste = Array.isArray(j.r) ? j.r : [];
const ok = liste.filter(e => e && /^[0-9]{1,18}$/.test(String(e.beitrag_id)) && typeof e.url === 'string' && /^https:\/\/\S+$/.test(e.url) && e.url.length <= 2000).slice(0, 30);
if (!ok.length) return [{ json: { laden: false, kanal_id: k.kanal_id } }];
return ok.map(e => ({ json: { laden: true, kanal_id: k.kanal_id, beitrag_id: String(e.beitrag_id), url: e.url } }));

// Bild lesen – TALENTS 2, Migration 193 (Stefan 01.11.2026, „Bild speichern“): Vorschaubilder der Storys einmal und dauerhaft speichern, solange die
// Meta-Adresse noch gilt (gleicher Lauf wie der Abruf). Abgelaufene Storys bleiben ohne Bild. Ein Fehler beim Laden oder Speichern lässt den Lauf nie
// scheitern; ohne gespeichertes Bild bleibt es bei der Adresse wie bisher.
// Antworten von „Bild verkleinern“ in derselben Reihenfolge wie „Bilder verteilen“. Nur ein verkleinertes Bild (ohne Fehler) bis 150 KB, JPEG oder PNG
// am Dateikopf geprüft; sonst b64 leer (zu groß oder Verkleinern fehlgeschlagen: nichts speichern, es bleibt bei der Adresse). Die Datei selbst geht nicht weiter.
const GRENZE = 153600;
const V = $('Bilder verteilen').all();
const ein = $input.all();
const aus = [];
for (let i = 0; i < ein.length; i++) {
  const it = ein[i] || {};
  const j = it.json || {};
  const v = (V[i] || {}).json || {};
  const st = Number(j.statusCode);
  let b64 = '', grund = '';
  if (j.error || !it.binary || !it.binary.datei) grund = 'kein Bild';
  else if (st && (st < 200 || st > 299)) grund = 'HTTP ' + st;
  else {
    try {
      const b = await this.helpers.getBinaryDataBuffer(i, 'datei');
      const jpg = b.length > 3 && b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff;
      const png = b.length > 8 && b[0] === 0x89 && b[1] === 0x50 && b[2] === 0x4e && b[3] === 0x47 && b[4] === 0x0d && b[5] === 0x0a && b[6] === 0x1a && b[7] === 0x0a;
      if (!b.length || b.length > GRENZE) grund = 'Größe';
      else if (!jpg && !png) grund = 'kein JPEG oder PNG';
      else b64 = b.toString('base64');
    } catch (e) { grund = 'nicht lesbar'; }
  }
  aus.push({ json: { kanal_id: v.kanal_id, beitrag_id: v.beitrag_id, b64, grund } });
}
return aus;

